def de_casteljau(points, t):
    n = len(points)
    coefs = list(points)
    for r in range(1, n):
        for i in range(n - r):
            x = (1 - t) * coefs[i][0] + t * coefs[i+1][0]
            y = (1 - t) * coefs[i][1] + t * coefs[i+1][1]
            coefs[i] = (x, y)
    return coefs[0]

